      "description": "It defines a basic API for transcoding a media and query the status of a\nJob. The underlying provider should handle the profileSpec as deisired (it\nmight be a JSON, or an XML, or anything else.",
      "type": "object",
      "title": "TranscodingProvider represents a provider of transcoding.",
      "properties": {
        "Healthcheck": {
          "description": "Healthcheck should return nil if the provider is currently available\nfor transcoding videos, otherwise it should return an error\nexplaining what's going on.",
          "type": "string"
        }
      },
      "x-go-package": "github.com/nytm/video-transcoding-api/provider"
    }
